// Title: Embed custom CSS and keep styles inline when converting Excel to HTML with Aspose.Cells for .NET
// Common Searches: how to add a custom <style> block to HTML generated by Aspose.Cells in C# | Aspose.Cells export Excel to HTML without linking external stylesheet | C# insert custom CSS classes into the head of Aspose.Cells HTML output | disable external CSS files when saving a workbook as HTML using Aspose.Cells | embed inline CSS while converting an .xlsx file to .html with Aspose.Cells .NET
// Tags: Aspose.Cells HtmlSaveOptions embed inline styles | C# insert custom CSS into Aspose.Cells HTML output | Excel to HTML conversion with embedded stylesheet Aspose.Cells | disable external stylesheet in Aspose.Cells HTML export | custom style block insertion for generated HTML Aspose.Cells

using System;
using System.IO;
using Aspose.Cells;

namespace AsposeCellsHtmlExport
{
    // The example loads an Excel workbook, saves it as HTML using Aspose.Cells, then reads the generated file, injects a <style> element containing custom CSS definitions before the closing </head> tag, and writes the modified HTML back, ensuring all styling is embedded and no external CSS files are referenced.
    class Program
    {
        static void Main(string[] args)
        {
            const string inputPath = "input.xlsx";
            const string outputPath = "output.html";

            // Verify that the input workbook exists
            if (!File.Exists(inputPath))
            {
                Console.WriteLine($"Input file '{inputPath}' not found.");
                return;
            }

            try
            {
                // Load the workbook
                Workbook workbook = new Workbook(inputPath);

                // Configure HTML save options
                HtmlSaveOptions htmlOptions = new HtmlSaveOptions(SaveFormat.Html);
                // By default Aspose.Cells embeds style information into the HTML.
                // If needed, additional options can be set here.

                // Save the workbook as HTML
                workbook.Save(outputPath, htmlOptions);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error during workbook conversion: {ex.Message}");
                return;
            }

            // Custom CSS to be embedded in the generated HTML
            string customCss = @"
    /* Custom CSS for the exported HTML */
    .highlight { background-color: #ffeb3b; font-weight: bold; }
    .title { font-size: 18pt; color: #2e7d32; }
    ";

            // Insert the custom CSS into the <head> section of the HTML file
            try
            {
                if (File.Exists(outputPath))
                {
                    string htmlContent = File.ReadAllText(outputPath);
                    const string headCloseTag = "</head>";
                    string cssBlock = $"<style>{customCss}</style>";

                    if (htmlContent.Contains(headCloseTag))
                    {
                        htmlContent = htmlContent.Replace(headCloseTag, cssBlock + headCloseTag);
                        File.WriteAllText(outputPath, htmlContent);
                    }
                }
                else
                {
                    Console.WriteLine($"Output file '{outputPath}' was not created.");
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error while inserting custom CSS: {ex.Message}");
                return;
            }

            Console.WriteLine($"Workbook successfully exported to '{outputPath}'.");
        }
    }
}
